#include "portable/game/resources/database.h"
#include <stdio.h>
int main(void) { PortableDatabase db; PortableDbRecord r; int ids[]={0,1,2,3,4,5}; int ks[]={7,8}; if(portable_db_open(&db,"assets/HCEGANT")!=PORTABLE_DB_OK){puts(db.error);return 1;} for(int i=0;i<6;i++) for(int j=0;j<2;j++){PortableDbStatus s=portable_db_load(&db,(int16_t)ids[i],(int16_t)ks[j],&r); if(s){printf("miss id=%d kind=%d status=%s\n",ids[i],ks[j],portable_db_status_string(s));continue;} printf("id=%d kind=%d flags=%u size=%zu head=",ids[i],ks[j],r.index_flags,r.size); for(size_t k=0;k<(r.size<20?r.size:20);k++) printf("%02x",r.data[k]); if(r.size>=4){unsigned w=r.data[0]|r.data[1]<<8,h=r.data[2]|r.data[3]<<8;size_t rb=(w+7)/8;printf(" width=%u height=%u rowBytes=%zu one=%zu four=%zu",w,h,rb,4+rb*h,4+rb*h*4);}puts(""); portable_db_record_free(&r);} portable_db_close(&db);return 0;}
